def is_multiply_prime(a):
    """Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    # Check if a is the product of exactly 3 prime numbers
    # The product of 3 primes could be:
    # 1. Three distinct primes: p1 * p2 * p3
    # 2. Two same primes and one different: p1 * p1 * p2
    # 3. Three same primes: p1 * p1 * p1
    # But note: the problem says "multiplication of 3 prime numbers", which means
    # a = p * q * r where p, q, r are primes (they can be the same or different)

    # We need to check if a can be factored into exactly 3 prime factors (counting multiplicity)
    # i.e., the total number of prime factors (with multiplicity) is exactly 3

    if a < 2:
        return False

    count = 0
    n = a
    # Try dividing by small primes
    for p in range(2, int(n**0.5) + 1):
        if n % p == 0:
            while n % p == 0:
                n //= p
                count += 1
                if count > 3:
                    return False
    if n > 1:
        count += 1

    return count == 3

