    dist_to_ceil = abs(num - ceil_val)

    if dist_to_floor < dist_to_ceil:
        return int(floor_val)
    elif dist_to_ceil < dist_to_floor:
        return int(ceil_val)
    else:
        # Equidistant: round away from zero
        if num > 0:
            return int(ceil_val)
        else:
            return int(floor_val)
